function renderGlobalAttributes(){let panel=$('#attribute-manager');if(!panel){panel=document.createElement('section');panel.id='attribute-manager';panel.className='attribute-manager';panel.innerHTML='<div><h3>Atributos de todas as fichas</h3><p class="muted">Somente a mestra pode alterar. Uma mudança aqui é aplicada a todos os personagens.</p></div><div id="global-attributes" class="global-attributes"></div><div class="row-actions"><button id="add-global-attribute" class="ghost small-btn">＋ Atributo</button><button id="save-global-attributes" class="primary small-btn">Aplicar em todas as fichas</button></div>';$('#users-modal .users-layout').before(panel);const backup=document.createElement('section');backup.className='attribute-manager backup-manager';backup.innerHTML='<div><h3>Backup da campanha</h3><p class="muted">Guarda fichas, configurações e imagens da VPS em um único arquivo.</p></div><div class="row-actions"><button id="export-backup" class="ghost">Criar backup</button><button id="restore-backup" class="danger">Restaurar backup</button></div>';panel.after(backup);$('#export-backup').onclick=async()=>{try{if(await window.rpg.exportBackup())toast('Backup criado','O arquivo completo foi salvo.')}catch(error){toast('Não foi possível criar o backup',error.message,true)}};$('#restore-backup').onclick=async()=>{if(!confirm('Restaurar um backup substituirá as fichas e configurações atuais da campanha. Deseja continuar?'))return;try{const data=await window.rpg.restoreBackup();if(!data)return;applySessionDb(data);$('#users-modal').classList.add('hidden');toast('Backup restaurado','As fichas, configurações e imagens foram restauradas.')}catch(error){toast('Não foi possível restaurar',error.message,true)}}}const names=db.settings?.attributeNames||Object.keys(draft?.attributes||{});$('#global-attributes').innerHTML=names.map((name,index)=>`<label><span>${index+1}</span><input value="${esc(name)}" data-global-attribute><button class="remove" data-remove-global-attribute="${index}">×</button></label>`).join('');$('#add-global-attribute').onclick=()=>{db.settings.attributeNames=[...names,'Novo atributo'];renderGlobalAttributes()};document.querySelectorAll('[data-remove-global-attribute]').forEach(button=>button.onclick=()=>{db.settings.attributeNames=names.filter((_,index)=>index!==n(button.dataset.removeGlobalAttribute));renderGlobalAttributes()});$('#save-global-attributes').onclick=async()=>{const values=[...document.querySelectorAll('[data-global-attribute]')].map(input=>input.value.trim()).filter(Boolean);try{db=await window.rpg.updateAttributes(values);draft=clone(current());renderGlobalAttributes();render();toast('Atributos atualizados','A alteração foi aplicada em todas as fichas.')}catch(error){toast('Não foi possível alterar',error.message||String(error),true)}}}
