const $ = s => document.querySelector(s);
const esc = value => String(value ?? '').replace(/[&<>'"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const uid = () => crypto.randomUUID();
const clone = value => JSON.parse(JSON.stringify(value));
const n = value => Number(value) || 0;
const normalizeName = value => String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('pt-BR').replace(/[^a-z0-9]/g,'');
const skillNameKey=value=>{const key=normalizeName(value);return key.length>3&&key.endsWith('s')?key.slice(0,-1):key};
function canonicalSkillName(value){const found=allSkillCatalog().find(skill=>skillNameKey(skill.name)===skillNameKey(value));return found?.name||String(value||'').trim()}
function dedupeSkillList(items){const merged=[];for(const raw of items||[]){const item={...raw,name:canonicalSkillName(raw.name)},key=skillNameKey(item.name),existing=merged.find(entry=>skillNameKey(entry.name)===key);if(!existing){merged.push(item);continue}for(const field of ['value','bonus','current','goal','successCount','failureCount'])if(n(item[field])>n(existing[field]))existing[field]=item[field]}return merged}
function normalizeCharacterSkills(character){if(!character)return;character.skills=dedupeSkillList(character.skills);character.quests=dedupeSkillList(character.quests);character.learning=dedupeSkillList(character.learning);const learned=new Set(character.skills.map(skill=>skillNameKey(skill.name)));character.learning=character.learning.filter(skill=>!learned.has(skillNameKey(skill.name)))}
function isMaster(){return db?.sessionUser?.role==='admin'}
function canViewCurrentHistory(){return isMaster()||Boolean(draft?.ownerUserId&&draft.ownerUserId===db?.sessionUser?.id)}
function ideaCreation(idea){
 if(!idea)return;
 const creations=draft?.creations||[],linked=creations.find(item=>idea.id&&item.ideaId===idea.id);
 if(linked)return linked;
 if(idea.creationCompleted&&idea.completedCreation)return idea.completedCreation;
 const matches=creations.filter(item=>!item.ideaId&&normalizeName(item.name)===normalizeName(idea.name));
 const ideas=(draft?.ideas||[]).filter(item=>normalizeName(item.name)===normalizeName(idea.name));
 return matches.length===1&&ideas.length===1?matches[0]:undefined;
}
function creationComplete(creation){return Boolean(creation&&n(creation.requirement)>0&&n(creation.current)<=0)}
function removeCharacterItem(type,index){
 if(!isMaster()&&['skills','learning','quests','creations'].includes(type))return false;
 const item=draft?.[type]?.[index];if(!item)return false;
 if(type==='ideas'){const linked=ideaCreation(item);draft.creations=(draft.creations||[]).filter(c=>c!==linked&&!(item.id&&c.ideaId===item.id));expandedIdeas.clear()}
 if(type==='abilities')expandedAbilities.clear();
 draft[type].splice(index,1);rollSkills.clear();markDirty('Item excluído');render();return true;
}
function learningOccupied(){return Boolean((draft?.creations||[]).length)}
function availableLearningIdeas(){return (draft?.ideas||[]).filter(idea=>idea.status==='Em desenvolvimento'&&!idea.creationCompleted&&!creationComplete(ideaCreation(idea)))}
function startIdeaLearning(idea){
 if(!(draft?.ideas||[]).includes(idea))throw new Error('A ficha foi atualizada. Abra a lista novamente.');
 if(learningOccupied())throw new Error('Conclua ou remova a criação atual antes de iniciar outra.');
 if(!availableLearningIdeas().includes(idea))throw new Error('Esta ideia não está disponível para aprendizado.');
 const requirement=n(idea.initialRequirement);if(requirement<1)throw new Error('A mestre precisa definir o requisito inicial desta ideia.');
 idea.id||=uid();draft.creations||=[];
 draft.creations.push({id:uid(),ideaId:idea.id,type:'Criação de habilidade',name:idea.name||'Nova habilidade',current:requirement,requirement,progressMode:'countdown',initialized:true});
 rollSkills.clear();markDirty(`${idea.name||'Habilidade'} adicionada ao aprendizado`);render();
}
function openLearningPicker(){
 const ideas=availableLearningIdeas(),occupied=learningOccupied(),modal=document.createElement('div');
 modal.className='modal';modal.setAttribute('role','dialog');modal.setAttribute('aria-modal','true');modal.setAttribute('aria-labelledby','learning-picker-title');
 modal.innerHTML=`<div class="modal-card"><div class="section-head"><div><h2 id="learning-picker-title">Escolher habilidade em desenvolvimento</h2><p>${occupied?'Conclua a criação atual para liberar o próximo aprendizado.':'Escolha uma ideia para iniciar o aprendizado. Apenas uma criação por vez.'}</p></div><button class="ghost" data-close-learning>Fechar</button></div><div class="idea-list">${ideas.length?ideas.map((idea,index)=>`<article class="user-assignment-card"><div class="user-assignment-head"><div><strong>${esc(idea.name||'Nova habilidade')}</strong><small>${esc(abilityTypeLabel(idea.type))} · Requisito inicial: ${n(idea.initialRequirement)||'aguardando a mestre'}</small></div><button class="primary small-btn" data-start-learning="${index}" ${occupied||n(idea.initialRequirement)<1?'disabled':''}>Aprender</button></div></article>`).join(''):empty('Nenhuma ideia disponível. Em Ideias de habilidade, coloque uma ideia aprovada em desenvolvimento.')}</div></div>`;
 const close=()=>{modal.remove();document.removeEventListener('keydown',onKey);$('#add-creation')?.focus()};
 const onKey=event=>{if(event.key==='Escape')close()};document.addEventListener('keydown',onKey);
 modal.addEventListener('click',event=>{if(event.target===modal||event.target.closest('[data-close-learning]'))return close();const button=event.target.closest('[data-start-learning]');if(!button)return;try{startIdeaLearning(ideas[n(button.dataset.startLearning)]);close();toast('Aprendizado iniciado','Salve as alterações para sincronizar a criação online.')}catch(error){toast('Não foi possível iniciar',error.message,true)}});
 document.body.append(modal);modal.querySelector('[data-start-learning]:not([disabled]), [data-close-learning]')?.focus();
}
function ideaStatusOptions(idea){
 const status=idea.status||'Rascunho',creation=ideaCreation(idea),complete=creationComplete(creation);
 let options;
 if(['Rascunho','Pedido para a mestre','Recusada'].includes(status))options=isMaster()?['Rascunho','Pedido para a mestre','Aprovada','Recusada']:['Rascunho','Pedido para a mestre'];
 else if(status==='Aprovada')options=['Aprovada','Em desenvolvimento'];
 else if(status==='Em desenvolvimento')options=complete?['Em desenvolvimento','Finalizada']:['Em desenvolvimento'];
 else options=[status];
 if(complete&&!options.includes('Finalizada'))options.push('Finalizada');
 if(complete)options=[status,'Finalizada'];
 return [...new Set(options)].map(value=>`<option ${value===status?'selected':''}>${value}</option>`).join('');
}
document.addEventListener('change',event=>{
 if(event.target.matches('[data-arr="abilities"][data-key="useCurrent"], [data-arr="abilities"][data-key="useGoal"]')){render();return}
 const input=event.target;if(!input.matches('[data-idea-status]'))return;
 const index=n(input.dataset.ideaStatus),idea=draft?.ideas?.[index];if(!idea)return;
 if(input.value==='Em desenvolvimento'){
  event.stopImmediatePropagation();if(idea.status!=='Aprovada'||n(idea.initialRequirement)<1){input.value=idea.status||'Rascunho';toast('Aprovação necessária','A mestre precisa aprovar e definir o requisito inicial.',true);return}
  idea.status='Em desenvolvimento';markDirty(`${idea.name||'Ideia'} em desenvolvimento`);render();toast('Ideia em desenvolvimento','Na ficha, clique em Adicionar criação e escolha a habilidade para aprender.');return;
 }
 if(input.value!=='Finalizada')return;
 event.stopImmediatePropagation();const creation=ideaCreation(idea);
 if(!creationComplete(creation)){input.value=idea.status||'Rascunho';toast('Criação ainda incompleta','O valor restante precisa chegar a zero.',true);return}
 draft.abilities||=[];
 const type=['passive','active','ultimate'].includes(idea.type)?idea.type:'active';
 const existing=draft.abilities.find(ability=>normalizeName(ability.name)===normalizeName(idea.name));
 if(existing){existing.effect=idea.effect||existing.effect;existing.type=type}
 else draft.abilities.push({name:idea.name||'Nova habilidade',effect:idea.effect||'',level:1,type,useCurrent:0,useGoal:25,successAdjustment:0});
 draft.creations=draft.creations.filter(item=>item!==creation);draft.ideas.splice(index,1);expandedIdeas.clear();
 markDirty(`${idea.name||'Habilidade'} finalizada e transferida`);render();toast('Habilidade finalizada','Adicionada em Habilidades. Você já pode iniciar outro aprendizado.');
},true);
