 draft.rollHistory ||= [];draft.rollHistory.unshift({id:`roll-${Date.now()}-${Math.random().toString(36).slice(2,8)}`,at:new Date().toISOString(),userName:typeof db!=='undefined'?db.sessionUser?.name||'':'',progressType:rollProgressType,formula:roll.formula,attribute:roll.attribute||'',attributeValue:n(roll.attributeValue),items:roll.selected.map(item=>({name:item.name||'',kind:item.creation?'creation':item.ability?'ability':item.quest?'quest':item.learning?'learning':item.temporary?'temporary':'skill'})),effects:(roll.effects||[]).map(item=>item.name||''),outcome,successTarget:n(roll.successTarget)||50});if(draft.rollHistory.length>200)draft.rollHistory.length=200;
