 const close=()=>modal.remove(),type=modal.querySelector('#new-ability-type'),level=modal.querySelector('#new-ability-level'),goal=modal.querySelector('#new-ability-goal');
 const syncGoal=()=>{const maximum=globalThis.RpgProgression?.abilityMaxLevel(type.value),value=Math.max(1,Math.floor(n(level.value)||1));if(maximum!==null&&value>maximum)level.value=maximum;goal.value=globalThis.RpgProgression?.abilityUseGoal(Math.max(1,n(level.value)))||25};
