function updatePhotoPreview(){
 photoSettingsDraft={fit:$('#photo-fit').value,x:n($('#photo-x').value),y:n($('#photo-y').value),zoom:n($('#photo-zoom').value)};
 const img=$('#photo-preview-image'),scale=photoSettingsDraft.zoom/100,tx=50-scale*photoSettingsDraft.x,ty=50-scale*photoSettingsDraft.y;img.style.objectFit=photoSettingsDraft.fit;img.style.objectPosition='center';img.style.transformOrigin='0 0';img.style.transform=`translate(${tx}%,${ty}%) scale(${scale})`;
 $('#photo-x-value').textContent=`${photoSettingsDraft.x}%`;$('#photo-y-value').textContent=`${photoSettingsDraft.y}%`;$('#photo-zoom-value').textContent=`${photoSettingsDraft.zoom}%`;
}
