function applyPhotoEditor(){draft.portraitSettings={...photoSettingsDraft};markDirty('Enquadramento da foto atualizado');closePhotoEditor();render();toast('Enquadramento aplicado','Salve as alterações para manter a posição da foto.')}

async function paintAppearancePreview(){const path=db.sessionUser?.appearance?.backgroundPath||'',preview=$('#appearance-background-preview');preview.style.backgroundImage='';preview.innerHTML='<span>Nenhuma imagem escolhida</span>';if(path){const image=await imageData(path);if(image){preview.style.backgroundImage=`linear-gradient(#0003,#0003),url("${image}")`;preview.innerHTML='<span>Imagem atual</span>';}}}
function syncAppearanceHex(){for(const color of document.querySelectorAll('.appearance-colors input[type="color"]')){const hex=$(`#${color.id}-hex`);if(hex){hex.value=color.value.toUpperCase();hex.classList.remove('invalid')}}}
function normalizeAppearanceHex(value){const hex=value.trim().replace(/^#/,'');return /^[0-9a-f]{6}$/i.test(hex)?`#${hex.toUpperCase()}`:null}
document.querySelector('.appearance-colors').insertAdjacentHTML('beforeend','<label>Notificações<input id="appearance-notification" type="color"></label>');
for(const color of document.querySelectorAll('.appearance-colors input[type="color"]')){const hex=document.createElement('input');hex.type='text';hex.id=`${color.id}-hex`;hex.className='appearance-hex';hex.maxLength=7;hex.placeholder='#RRGGBB';hex.setAttribute('aria-label',`Código hexadecimal de ${color.parentElement.textContent.trim()}`);hex.spellcheck=false;color.insertAdjacentElement('afterend',hex);color.addEventListener('input',()=>{hex.value=color.value.toUpperCase();hex.classList.remove('invalid');previewAppearance()});hex.addEventListener('input',()=>{const normalized=normalizeAppearanceHex(hex.value);hex.classList.toggle('invalid',!normalized);if(normalized){color.value=normalized;previewAppearance()}});hex.addEventListener('blur',()=>{const normalized=normalizeAppearanceHex(hex.value);if(normalized){hex.value=normalized;color.value=normalized}})}
$('#appearance-modal').addEventListener('input',event=>{if(event.target.matches('[id^="appearance-"]:not(.appearance-hex):not([type="color"])'))previewAppearance()});
$('#appearance-modal').addEventListener('change',event=>{if(event.target.matches('[id^="appearance-"]:not(.appearance-hex):not([type="color"])'))previewAppearance()});
function renderAppearancePresets(){const presets=db.sessionUser?.appearance?.presets||[],select=$('#appearance-preset-select'),selected=select.value;select.innerHTML=`<option value="">Selecione um estilo salvo...</option>${presets.map(preset=>`<option value="${esc(preset.id)}">${esc(preset.name)}</option>`).join('')}`;if(presets.some(preset=>preset.id===selected))select.value=selected;$('#appearance-preset-load').disabled=!select.value;$('#appearance-preset-overwrite').disabled=!select.value;$('#appearance-preset-delete').disabled=!select.value}
async function openAppearance(){const appearance={...appearanceDefaults,...(db.sessionUser?.appearance||{})};for(const key of Object.keys(appearanceDefaults)){const control=$(`#appearance-${key}`);if(!control)continue;if(control.type==='checkbox')control.checked=Boolean(appearance[key]);else control.value=appearance[key]}syncAppearanceHex();renderAppearancePresets();await paintAppearancePreview();$('#appearance-modal').classList.remove('hidden');try{const backup=await window.rpg.loadAppearanceBackup(),changed=backup&&Object.keys(appearanceDefaults).some(key=>backup[key]!==undefined&&backup[key]!==appearance[key]);$('#appearance-recover').classList.toggle('hidden',!changed)}catch{$('#appearance-recover').classList.add('hidden')}}
function appearanceFromControls(){for(const hex of document.querySelectorAll('.appearance-hex')){const normalized=normalizeAppearanceHex(hex.value);if(!normalized){hex.classList.add('invalid');hex.focus();throw new Error('Código hexadecimal inválido. Use seis dígitos, por exemplo #A1B2C3.')}hex.value=normalized;$(`#${hex.id.slice(0,-4)}`).value=normalized}const appearance={};for(const key of Object.keys(appearanceDefaults)){const control=$(`#appearance-${key}`);appearance[key]=control.type==='checkbox'?control.checked:control.value}return appearance}
function setAppearanceControls(appearance){for(const key of Object.keys(appearanceDefaults)){const control=$(`#appearance-${key}`);if(!control)continue;if(control.type==='checkbox')control.checked=Boolean(appearance[key]);else control.value=appearance[key]??appearanceDefaults[key]}syncAppearanceHex();previewAppearance()}
