function renderUsersManager(){
 if(db.sessionUser?.role!=='admin')return;
 const users=db.users||[],characters=db.characters||[];
 const layout=$('#users-modal .users-layout'),userSection=$('#users-list')?.closest('section'),ownerSection=$('#character-owners')?.closest('section');
 if(layout)layout.classList.add('users-by-player');if(ownerSection)ownerSection.classList.add('hidden');
 $('#users-list').innerHTML='<h3>Jogadores e personagens</h3>'+users.map(user=>{const owned=characters.filter(character=>character.ownerUserId===user.id),available=characters.filter(character=>character.ownerUserId!==user.id);return `<article class="user-assignment-card"><div class="user-assignment-head"><div><strong>${esc(user.name)}</strong><small>@${esc(user.username)}</small></div><div><span class="role-badge ${user.role==='admin'?'admin':''}">${user.role==='admin'?'Mestre':'Jogador'}</span>${user.id!==db.sessionUser.id?`<button class="danger small-btn delete-user-button" data-delete-user="${user.id}">Excluir usuário</button>`:''}</div></div><div class="assigned-characters"><span>Personagens deste usuário</span>${owned.length?owned.map(character=>`<b>${esc(character.name)}</b>`).join(''):'<em>Nenhum personagem atribuído</em>'}</div><div class="field assign-character-field"><label>Atribuir personagem</label><select data-assign-to-user="${user.id}"><option value="">Selecione uma ficha...</option>${available.map(character=>`<option value="${character.id}">${esc(character.name)}</option>`).join('')}</select></div></article>`}).join('');
 document.querySelectorAll('[data-assign-to-user]').forEach(el=>el.addEventListener('change',async()=>{if(!el.value)return;try{db=await window.rpg.assignCharacter(el.value,el.dataset.assignToUser);draft=clone(current());renderUsersManager();renderSidebar();toast('Personagem atribuído','A ficha foi colocada na conta selecionada.')}catch(error){toast('Não foi possível atribuir',error.message,true)}}));
 document.querySelectorAll('[data-delete-user]').forEach(el=>el.addEventListener('click',async()=>{if(!confirm('Excluir este usuário? As fichas dele voltarão para a conta da mestre.'))return;try{db=await window.rpg.deleteUser(el.dataset.deleteUser);renderUsersManager();toast('Usuário excluído')}catch(error){toast('Não foi possível excluir',error.message,true)}}));
}
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});

let onlineReloadTimer,onlineReloadBusy=false,onlinePendingNotice=false,pendingOnlineSnapshot=null,onlinePointerDown=false,pendingOnlineApplyTimer;
const editableFocused=()=>document.activeElement?.matches('input:not([readonly]):not([disabled]),textarea:not([readonly]):not([disabled]),select:not([disabled])');
function schedulePendingOnlineSnapshot(delay=600){clearTimeout(pendingOnlineApplyTimer);pendingOnlineApplyTimer=setTimeout(()=>{if(!pendingOnlineSnapshot||editableFocused()||onlinePointerDown)return;const latest=pendingOnlineSnapshot;pendingOnlineSnapshot=null;applyOnlineSnapshot(latest)},delay)}
document.addEventListener('pointerdown',()=>{onlinePointerDown=true},true);
for(const eventName of ['pointerup','pointercancel'])document.addEventListener(eventName,()=>{onlinePointerDown=false;schedulePendingOnlineSnapshot()},true);
function applyOnlineSnapshot(latest){
 if(!db)return;
 const editing=editableFocused();
 const pointsModalOpen=!$('#point-notifications-modal').classList.contains('hidden');
 if(editing||onlinePointerDown||document.querySelector('.modal:not(.hidden):not(#point-notifications-modal)')){pendingOnlineSnapshot=latest;return}
 if(JSON.stringify([db.characters,db.settings,db.users])===JSON.stringify([latest.characters,latest.settings,latest.users]))return;
 if(dirty){db.characters=latest.characters;db.users=latest.users;const changed=latest.characters.find(c=>c.id===currentId)?._remoteVersion!==draft?._remoteVersion;if(changed&&!onlinePendingNotice){onlinePendingNotice=true;toast('A ficha recebeu uma atualização','Suas alterações foram preservadas. Ao salvar, mudanças em campos diferentes serão combinadas.')}refreshPointGrantNotifications();renderSidebar();showNewPointGrantToast();if(pointsModalOpen)openPointGrantNotifications();return}
 onlinePendingNotice=false;const selected=currentId;db=latest;
 const next=db.characters.find(c=>c.id===selected&&!c.archived)||db.characters.find(c=>!c.archived);
 currentId=next?.id||null;draft=next?clone(next):null;savedSharedSolos=sharedSolos();
 if(!next)activeView=isMaster()?'archived':'empty';else if(activeView==='empty')activeView='sheets';
 render();clean();showNewPointGrantToast();if(pointsModalOpen)openPointGrantNotifications();
}
document.addEventListener('focusin',()=>clearTimeout(pendingOnlineApplyTimer),true);
document.addEventListener('focusout',()=>schedulePendingOnlineSnapshot(),true);
function reloadUpdatedCharacters(){
 clearTimeout(onlineReloadTimer);onlineReloadTimer=setTimeout(async()=>{
  if(!db||onlineReloadBusy)return;onlineReloadBusy=true;
  try{
   const latest=await window.rpg.load();applyOnlineSnapshot(latest);
  }catch(error){if(db.online)toast('Conexão online',error.message||String(error),true)}finally{onlineReloadBusy=false}
 },200);
}
window.rpg.onOnlineChange?.(reloadUpdatedCharacters);
setInterval(()=>{if(db&&!db.online)reloadUpdatedCharacters()},5000);
window.rpg.onUpdateStatus(status=>showUpdateProgress(status));
$('#sheet-lock').addEventListener('click',()=>{if(db?.sessionUser?.role!=='player'||!currentId)return;if(editingCharacterId===currentId){if(dirty){toast('Salve antes de bloquear','Salve ou descarte as alterações pendentes primeiro.',true);return}editingCharacterId=null;toast('Ficha bloqueada','Use o cadeado ao lado do nome para voltar a editar.')}else{editingCharacterId=currentId;toast('Edição liberada','Agora você pode alterar esta ficha.')}render()});
